"""Explicit source transcriptions of T2S workbook conceptual models; no inferred flow directions."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
from extract_workbooks import write
JOB='job-000001';OUT=ROOT/'work/t2s-workbook-models';results=json.loads((ROOT/'work/workbook-results.json').read_text('utf-8'))
def e(a,b,label='',kind='--',a_card=None,b_card=None):
 r=dict(a=a,b=b,label=label,kind=kind)
 if a_card:r['a_card']=a_card
 if b_card:r['b_card']=b_card
 return r
def g(a,b):return e(a,b,kind='--|>')
def ns(names,package='not printed in figure'):return [dict(id=n,name=n,package=package,stereotype='BusinessComponent') for n in names.split()]
models=[]
def add(sid,title,nodes,edges,meaning,**extra):
 d=next(d for r in results if r['source_id']==sid for d in r['diagrams'] if d['figure_id']=='fig-0002');models.append(dict(source_id=sid,id='fig-0002',title=title,nodes=nodes,edges=edges,meaning=meaning,source=d,**extra))
add('src-000348','T2S billing conceptual model',ns('System CashAccountService Account Invoice AccountIdentification LineItem Adjustment Product Price ProductCategory ProductQuantity Tax Country Party TaxRecord'),[e(a,b,kind='-->') for a,b in [('System','CashAccountService'),('System','Account'),('CashAccountService','Account'),('CashAccountService','Invoice'),('Account','Invoice'),('Account','AccountIdentification'),('Invoice','LineItem'),('LineItem','Adjustment'),('LineItem','Product'),('Product','Price'),('Product','ProductCategory'),('Product','ProductQuantity'),('Product','Tax'),('Tax','Country'),('Tax','Party'),('Tax','TaxRecord')]],'System has directed associations to cash-account service and account. Service and account each point to invoice; account points to account identification. Invoice points to line item, then adjustment/product. Product points to price, category, quantity and tax; tax points to country, party and tax record. These arrows belong to the source conceptual model and do not establish chronological billing activities or XML containment.')
nodes=ns('AccountService Account AccountRestriction DateTimePeriod ReportingService CashAccountService CashAccountMandate ContactPoint PhoneAddress PostalAddress ElectronicAddress BankOperation DebitCreditFacility CashManagementService BankTransaction OperationThreshold','DICO_BusinessComponents')
for n in nodes:
 if n['name']=='DateTimePeriod':n['package']='DICO_BusinessComponentsDataTypes';n['stereotype']=''
 if n['name']=='AccountRestriction':n['stereotype']=''
 if n['name'] in ['Account','CashAccountMandate','OperationThreshold']:n['package']='not printed in figure'
add('src-000352','T2S cash-account management conceptual model',nodes,[e('AccountService','Account'),e('Account','AccountRestriction'),e('AccountRestriction','DateTimePeriod','+ ValidityPeriod'),g('ReportingService','AccountService'),g('CashAccountService','AccountService'),e('ContactPoint','ReportingService','+ ReportingChannel / + RelatedReportingService'),g('PhoneAddress','ContactPoint'),g('PostalAddress','ContactPoint'),g('ElectronicAddress','ContactPoint'),g('BankOperation','CashAccountService'),g('DebitCreditFacility','CashAccountService'),g('CashManagementService','CashAccountService'),e('CashAccountService','CashAccountMandate','+ Services'),e('BankOperation','BankTransaction','- OperationType'),e('BankOperation','OperationThreshold')],'Cash-account and reporting services specialize account service. Cash-account service further generalizes bank operation, debit/credit facility and cash-management service; it connects mandate, while bank operation connects bank transaction and threshold. Contact-point channels specialize into phone, postal and electronic addresses. Account restriction connects a validity period. The displaced ReportingChannel/RelatedReportingService labels are attached to the ContactPoint–ReportingService association, independently confirmed by FullBusinessModel!A1000:F1000 and A3799:F3799. No message direction is implied.',extra_source_locations=['FullBusinessModel!A1000:F1000','FullBusinessModel!A3799:F3799'])
add('src-000355','T2S collateral-management reference-data conceptual model',ns('Collateral Security CollateralStatus SystemPartyRole SecuritiesIdentification PartyIdentificationInformation'),[e('Collateral','Security',kind='*--'),e('Collateral','CollateralStatus',kind='*--'),e('Collateral','SystemPartyRole'),e('SystemPartyRole','PartyIdentificationInformation',kind='*--'),e('Security','SecuritiesIdentification',kind='*--')],'Filled diamonds are retained at the source owner ends: Collateral composes Security and CollateralStatus; Security composes SecuritiesIdentification; SystemPartyRole composes PartyIdentificationInformation. Collateral and SystemPartyRole have a plain association. This records the supplied conceptual notation, without turning composition into database keys, XML containment or institutional ownership.')
add('src-000358','T2S collateral-reporting conceptual model',ns('SystemPartyRole ClearingMemberRole CashClearingSystemMember OrganisationIdentification Organisation FinancialInstitution System ClearingSystem CashClearingSystem AccountPartyRole AccountServicerRole Account SecuritiesAccount CashAccount Collateral CollateralValuation AssetHolding SecuritiesPricing Security SecuritiesBalance SecuritiesQuantity SecuritiesIdentification AccountIdentification GenericIdentification Scheme InformationPartyRole IdentificationIssuerRole'),[g('ClearingMemberRole','SystemPartyRole'),e('SystemPartyRole','System','+ PartyRole / + RelatedSystem'),e('ClearingMemberRole','CashClearingSystemMember','- ClearingSystemMemberIdentification'),e('CashClearingSystemMember','OrganisationIdentification','+ ClearingSystemMemberIdentificationType'),e('OrganisationIdentification','Organisation'),g('FinancialInstitution','Organisation'),g('ClearingSystem','System'),g('CashClearingSystem','ClearingSystem'),e('System','Account'),g('AccountServicerRole','AccountPartyRole'),e('AccountPartyRole','Account','+ PartyRole'),g('SecuritiesAccount','Account'),g('CashAccount','Account'),e('Account','Collateral','+ CollateralAccount / + RelatedCollateralProcess'),e('Collateral','CollateralValuation','+ Valuation'),e('Collateral','AssetHolding','- VariationMarginCollateral / + VariationMarginAssetHolding'),e('SecuritiesPricing','Security','+ Pricing'),e('Security','SecuritiesBalance','- Balance'),e('SecuritiesBalance','SecuritiesAccount'),e('SecuritiesBalance','SecuritiesQuantity','+ RelatedSubBalance / - SubBalanceQuantity'),e('Security','SecuritiesIdentification','+ IdentifiedSecurity / + Identification'),e('Account','AccountIdentification','+ Identification'),e('SecuritiesIdentification','GenericIdentification','+ RelatedSecuritiesIdentification'),e('AccountIdentification','GenericIdentification','+ IdentificationForAccount / - ProprietaryIdentification'),e('GenericIdentification','Scheme','+ Identification'),e('SecuritiesPricing','InformationPartyRole','+ Price'),e('InformationPartyRole','Scheme'),g('IdentificationIssuerRole','InformationPartyRole')],'The model links system membership and organisation identification to account, account servicing, securities/cash account types and collateral valuation/variation margin. Securities balance connects security, account and quantity. Securities and account identifications link generic identification and scheme; information and identification-issuer roles provide separately scoped identification context. Association labels near SecuritiesPricing and Security refer to different links: Pricing on price/security, IdentifiedSecurity and Identification on security/identification. No payment or reporting message direction is supplied.')
add('src-000367','T2S account-link reference-data conceptual model',ns('Account SecuritiesAccount CashAccount AccountIdentification PartyIdentificationInformation AccountLink'),[g('SecuritiesAccount','Account'),g('CashAccount','Account'),e('Account','AccountIdentification',kind='*-->'),e('Account','PartyIdentificationInformation',kind='*-->'),e('AccountLink','SecuritiesAccount',kind='*-->',a_card='1',b_card='1'),e('AccountLink','CashAccount',kind='*-->',a_card='1',b_card='1')],'SecuritiesAccount and CashAccount specialize Account. Account has directed composition to account identification and party-identification information. AccountLink has two directed composition associations, one to securities account and one to cash account, each with literal multiplicity 1 at both ends. The filled diamonds remain at Account or AccountLink; the arrowheads remain at the identification or linked-account end. These are source conceptual-model relationships, not inferred XML parentage.',multiplicity_note='The AccountLink–SecuritiesAccount and AccountLink–CashAccount links each print 1 at both ends. Those four values are preserved. No cardinality is inferred on other associations.')
nodes=ns('Status StatusReason PaymentStatus Scheme PostalAddress Document GenericIdentification DateTimePeriod System SystemPartyRole PartyIdentificationInformation PartyName InformationPartyRole OrganisationIdentification IdentificationIssuerRole','DICO_BusinessComponents')
for n in nodes:
 if n['name'] in ['Scheme','GenericIdentification','DateTimePeriod']:n['package']='DICO_BusinessComponentsDataTypes'
add('src-000370','T2S party reference-data conceptual model',nodes,[e('Status','StatusReason'),g('PaymentStatus','Status'),e('StatusReason','GenericIdentification','- RelatedStatusReason / + DataSourceScheme'),e('GenericIdentification','Scheme','+ Identification'),e('Scheme','DateTimePeriod','+ AssessmentValidityScheme / - AssessmentValidityPeriod'),e('PostalAddress','DateTimePeriod','- RelatedPostalAddress / + ValidityPeriod'),e('Document','GenericIdentification','- IdentifiedDocument / - DocumentIdentification'),e('GenericIdentification','PartyIdentificationInformation','- OtherIdentification / + RelatedPartyIdentification'),e('GenericIdentification','InformationPartyRole','+ PartyRole'),g('IdentificationIssuerRole','InformationPartyRole'),g('OrganisationIdentification','PartyIdentificationInformation'),e('PartyIdentificationInformation','PartyName','+ PartyIdentification'),e('PartyIdentificationInformation','DateTimePeriod','- RelatedIdentification / + ValidityPeriod'),e('System','DateTimePeriod','- VersionValidityPeriod'),e('SystemPartyRole','System','+ PartyRole / + RelatedSystem')],'Generic identification relates document, status reason, scheme, party identification and information-party role. Scheme, postal address, party identification and system each have separate validity-period relationships. Organisation identification specializes party-identification information, and identification issuer specializes information-party role. PaymentStatus specializes Status. SystemPartyRole links the system; it is a contextual role rather than a fixed institution.')
add('src-000373','T2S securities-account reference-data conceptual model',ns('System Balance CashBalance Role SystemPartyRole AccountPartyRole InformationPartyRole IdentificationIssuerRole Account SecuritiesAccount AccountIdentification GenericIdentification Scheme PostalAddress Country Market PartyIdentificationInformation PartyName OrganisationIdentification'),[e('System','Account'),e('Balance','Account'),g('CashBalance','Balance'),g('SystemPartyRole','Role'),g('AccountPartyRole','Role'),g('InformationPartyRole','Role'),g('IdentificationIssuerRole','InformationPartyRole'),e('AccountPartyRole','Account','+ PartyRole'),g('SecuritiesAccount','Account'),e('Account','AccountIdentification','+ Identification'),e('AccountIdentification','GenericIdentification','+ IdentificationForAccountCostReferencePattern / + CostReferencePattern'),e('GenericIdentification','Scheme','+ Identification / + Scheme'),e('GenericIdentification','PartyIdentificationInformation','- OtherIdentification / + RelatedPartyIdentification'),e('PartyIdentificationInformation','PartyName','+ PartyIdentification'),g('OrganisationIdentification','PartyIdentificationInformation'),e('Market','PartyIdentificationInformation','- IdentifiedMarket / - Identification'),e('Country','Market'),e('PostalAddress','Country','+ PostalAddressSpecification')],'Account links system, balance, party role and account identification; SecuritiesAccount specializes Account and CashBalance specializes Balance. System, account and information party roles specialize Role; identification issuer specializes information-party role. Account identification uses a generic cost-reference pattern, and generic identification links scheme and party identification. Country links market and postal address. The source’s account role and account entity hierarchies remain separate.')
for m in models:
 code='classDiagram\ndirection TB\n'
 for n in m['nodes']:code+='class '+n['id']+' {\n'+('<<'+n['stereotype']+'>>\n' if n['stereotype'] else '')+'}\n'
 for r in m['edges']:code+=r['a']+(' "'+r['a_card']+'"' if r.get('a_card') else '')+' '+r['kind']+(' "'+r['b_card']+'"' if r.get('b_card') else '')+' '+r['b']+(' : '+r['label'] if r['label'] else '')+'\n'
 m.update(mermaid=code,render_prefix=m['source_id']+'-'+m['id'],review_status='needs-review',package_note='Printed package labels and absent labels are preserved in the entity register; the reconstruction adds no package boundaries absent from the source.');m.setdefault('limitations',[])
 write(ROOT,OUT/m['source_id']/(m['render_prefix']+'.mmd'),code,JOB)
write(ROOT,OUT/'models.json',json.dumps(models,ensure_ascii=False,indent=2),JOB)
print(json.dumps([{'source_id':m['source_id'],'nodes':len(m['nodes']),'edges':len(m['edges'])} for m in models]))
